syntax.mysql:
WITH RECURSIVE name (col1, col2) AS (
  SELECT ...                      -- anchor
  UNION ALL
  SELECT ... FROM name WHERE ...  -- recursive member (terminates)
)
SELECT ... FROM name;

examples.mysql:
WITH RECURSIVE nums AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM nums WHERE n < 10
)
SELECT n FROM nums ORDER BY n;

