examples.mysql:
WITH RECURSIVE tri AS (
  SELECT 1 AS n, 1 AS total
  UNION ALL
  SELECT n + 1, total + n + 1 FROM tri WHERE n < 6
)
SELECT n, total FROM tri ORDER BY n;

